from webapishpnotprd.shpnotin shp
LEFT JOIN webapishpnotprd.shipmentinfos shipi on shipi.id = shp.shipmentinfosid
LEFT JOIN webapishpnotprd.WEIGHTANDDIMENSION shipwd on shipwd.id = shipi.WEIGHTANDDIMENSIONID
LEFT JOIN webapishpnotprd.dimensions shipd on shipd.id = shipwd.DIMENSIONSID
LEFT JOIN webapishpnotprd.weight shipw on shipw.id = shipwd.WEIGHTID
LEFT JOIN webapishpnotprd.routinginfos rinfo on rinfo.id = shp.routinginfosid
LEFT JOIN webapishpnotprd.SENDER sender on sender.id = shp.senderid
LEFT JOIN webapishpnotprd.customerinfos senderci on senderci.id = sender.customerinfosid
LEFT JOIN webapishpnotprd.senderaddress senderadd on senderadd.id = sender.SENDERADDRESSID
LEFT JOIN webapishpnotprd.sendercontact sendercon on sendercon.id = sender.SENDERCONTACTID
LEFT JOIN webapishpnotprd.sendergps sendergps on sendergps.id = sender.SENDERGPSID
LEFT JOIN webapishpnotprd.senderlegalentity senderlegal on senderlegal.id = sender.SENDERLEGALENTITYID 
LEFT JOIN webapishpnotprd.receiver rec on rec.id = shp.receiverid
LEFT JOIN webapishpnotprd.receiveraddress recadd on recadd.id = rec.RECEIVERADDRESSID
LEFT JOIN webapishpnotprd.receivercontact reccon on reccon.id = rec.RECEIVERCONTACTID
LEFT JOIN webapishpnotprd.receivergps recgps on recgps.id = rec.RECEIVERGPSID
LEFT JOIN webapishpnotprd.receiverlegalentity reclegal on reclegal.id = rec.RECEIVERLEGALENTITYID
LEFT JOIN webapishpnotprd.international inter on inter.id = shp.INTERNATIONALID
LEFT JOIN webapishpnotprd.camount intercamount on intercamount.id = inter.CAMOUNTID
LEFT JOIN webapishpnotprd.camountex intercamountx on intercamountx.id = inter.CAMOUNTEXID
LEFT JOIN webapishpnotprd.CADDRESS intercadd on intercadd.id = inter.CADDRESSID
LEFT JOIN webapishpnotprd.CGPS intergps on intergps.id = inter.CGPSID
LEFT JOIN webapishpnotprd.CCONTACT intercontact on intercontact.id = inter.CCONTACTID
LEFT JOIN webapishpnotprd.siaddress intersiadd on intersiadd.id = inter.SIADDRESSID
LEFT JOIN webapishpnotprd.sigps intersigps on intersigps.id = inter.SIGPSID
LEFT JOIN webapishpnotprd.sicontact intersicon on intersicon.id = inter.SICONTACTID
LEFT JOIN webapishpnotprd.INTERINVOICELINE line on line.INTERNATIONALID = inter.id
LEFT JOIN webapishpnotprd.CNETWEIGHT linenet on linenet.id = line.cnetweightid
LEFT JOIN webapishpnotprd.CGROSSWEIGHT linegross on linegross.id = line.CGROSSWEIGHTID
LEFT JOIN webapishpnotprd.IMAGE img on img.INTERNATIONALID = inter.id
LEFT JOIN webapishpnotprd.person pers on pers.id = shp.personid
LEFT JOIN webapishpnotprd.PERSADDRESS personadd on personadd.id = pers.PERSADDRESSID
LEFT JOIN webapishpnotprd.persgps persgps on persgps.id = pers.PERSGPSID
LEFT JOIN webapishpnotprd.delivery deliv on deliv.id = shp.deliveryid
LEFT JOIN webapishpnotprd.parcel parcel on parcel.shpnotid = shp.id
LEFT JOIN webapishpnotprd.PARCELINFOS pinfo on pinfo.id = parcel.PARCELINFOSID
LEFT JOIN webapishpnotprd.dimensions pinfod on pinfod.id = pinfo.DIMENSIONSID
LEFT JOIN webapishpnotprd.DECLAREDWEIGHT pinfodw on pinfodw.id = pinfo.DECLAREDWEIGHTID
LEFT JOIN webapishpnotprd.MEASUREDWEIGHT pinfomw on pinfomw.id = pinfo.MEASUREDWEIGHTID
LEFT JOIN webapishpnotprd.SERVICECODES psc on psc.id = parcel.SERVICECODESID
LEFT JOIN webapishpnotprd.HINS hins on hins.id = parcel.HINSID
LEFT JOIN webapishpnotprd.HINSAMOUNT hinsa on hinsa.id = hins.HINSAMOUNTID
LEFT JOIN webapishpnotprd.CIFCOST cif on cif.id = parcel.CIFCOSTID
LEFT JOIN webapishpnotprd.COD cod on cod.id = parcel.CODID
LEFT JOIN webapishpnotprd.NAMOUNT na on na.id = cod.NAMOUNTID
LEFT JOIN webapishpnotprd.ROD rod on rod.id = parcel.RODID
LEFT JOIN webapishpnotprd.DUTIES du on du.id = rod.DUTIESID
LEFT JOIN webapishpnotprd.TAXES ta on ta.id = rod.TAXESID
LEFT JOIN webapishpnotprd.CUSTOMSFEES cf on cf.id = rod.CUSTOMSFEESID
LEFT JOIN webapishpnotprd.EXTRA ex on ex.id = rod.EXTRAID
LEFT JOIN webapishpnotprd.message msg on msg.parcelid = parcel.id
LEFT JOIN webapishpnotprd.SWAP sw on sw.id = parcel.SWAPID
LEFT JOIN webapishpnotprd.SHIPINFO shipi on shipi.id = parcel.SHIPINFOID
LEFT JOIN webapishpnotprd.RETURNINFOS rinfos on rinfos.id = parcel.RETURNINFOSID
LEFT JOIN webapishpnotprd.RETADDRESS retadd on retadd.id = rinfos.RETADDRESSID
LEFT JOIN webapishpnotprd.RETCONTACT retcon on retcon.id = rinfos.RETCONTACTID
LEFT JOIN webapishpnotprd.RETGPS retgps on retgps.id = rinfos.RETGPSID
LEFT JOIN webapishpnotprd.HAZARDOUSSUBSTANCE haz on haz.parcelid = parcel.id
LEFT JOIN webapishpnotprd.EXPLWEIGHT exw on exw.id = haz.EXPLWEIGHTID
LEFT JOIN webapishpnotprd.SUBWEIGHT subw on subw.id = haz.SUBWEIGHTID
LEFT JOIN webapishpnotprd.GOODS good on good.id = parcel.GOODSID
LEFT JOIN webapishpnotprd.TEMPERATURE temp on temp.id = good.TEMPERATUREID
LEFT JOIN webapishpnotprd.ENRICHMENTS enr on enr.id = shp.ENRICHMENTSID
LEFT JOIN webapishpnotprd.BUSINESSTYPES enrbu on enrbu.id = enr.BUSINESSTYPESID
LEFT JOIN webapishpnotprd.RECEIVERADDRESSCORRECTED enrradd on enrradd.id = enr.RECEIVERADDRESSCORRECTEDID
LEFT JOIN webapishpnotprd.ADDRESSCORRECTIONJOURNEY enraddj on enraddj.id = enr.ADDRESSCORRECTIONJOURNEYID
--where shp.FLAGAS400 = 'N' and rownum <= 3000
